/** Real Fabric transactions, paid native placements, actual player slots and world/mounted custody. UNRUN. */
public final class ToolboxGameTests {
    private static final BlockPos P=new BlockPos(3,3,3),T=P.east(3);
    private record Fixture(NativeSurvivalTestPlayer session,ToolboxBlockEntity box,UUID uuid)implements AutoCloseable{public void close(){session.player().closeContainer();session.close();}}
    private static ItemStack diamonds(){var stack=new ItemStack(Items.DIAMOND);stack.set(DataComponents.CUSTOM_NAME,Component.literal("Original toolbox diamonds"));return stack;}
    private static ToolboxInventory stocked(int amount){var inventory=new ToolboxInventory();try(var tx=Transaction.openOuter()){if(inventory.insert(ItemVariant.of(diamonds()),amount,tx)!=amount)throw new IllegalStateException("Actual fixture stock must fit");tx.commit();}return inventory;}
    private static long count(Storage<ItemVariant> storage){long total=0;for(var view:storage)total+=view.getAmount();return total;}
    private static Fixture place(GameTestHelper h,int amount){h.setBlock(P.below(),Blocks.STONE);h.setBlock(P.south(2).below(),Blocks.STONE);var session=NativeSurvivalTestPlayer.join(h,Vec3.atCenterOf(h.absolutePos(P.south(2))));var player=session.player();UUID uuid=UUID.randomUUID();var item=new ItemStack(AllBlocks.TOOLBOXES.get(DyeColor.BROWN));item.set(AllDataComponents.TOOLBOX_UUID,uuid);item.set(AllDataComponents.TOOLBOX_INVENTORY,stocked(amount).frozenCopy());item.set(DataComponents.CUSTOM_NAME,Component.literal("Paid source toolbox"));player.setItemInHand(InteractionHand.MAIN_HAND,item);var support=h.absolutePos(P.below());h.assertTrue(item.useOn(new UseOnContext(player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(support).add(0,.5,0),Direction.UP,support,false))).consumesAction()&&item.isEmpty(),"Exactly one original native toolbox item is physically placed and debited");var box=h.getBlockEntity(P,ToolboxBlockEntity.class);h.assertTrue(uuid.equals(box.getUniqueId())&&count(box.inventory)==amount&&box.getDisplayName().getString().equals("Paid source toolbox"),"Exact original item UUID, custom name, filters and paid stock reach the real native BE");return new Fixture(session,box,uuid);}
    private static void equip(Fixture fixture,int slot){var player=fixture.session.player();new ToolboxEquipPacket(fixture.box.getBlockPos(),fixture.uuid,0,slot).handle(player);if(!ToolboxBindings.matches(player,ToolboxBindings.get(player,slot),fixture.box))throw new IllegalStateException("Actual loaded owner must accept the real binding");}
    @GameTest public void sixteenRealColorsHaveUncontainableItemsAndExactStorageAssociations(GameTestHelper h){h.assertValueEqual(AllBlocks.TOOLBOXES.size(),16,"All source colors registered");for(var color:DyeColor.values()){var block=AllBlocks.TOOLBOXES.get(color);h.assertTrue(block.getColor()==color&&block.asItem() instanceof ToolboxBlockItem&&!block.asItem().canFitInsideContainerItems()&&AllBlockEntityTypes.TOOLBOX.isValid(block.defaultBlockState())&&com.simibubi.create.api.contraption.storage.item.MountedItemStorageType.REGISTRY.get(block)==AllMountedStorageTypes.TOOLBOX,"Actual color item/native BE/mounted type registrations agree");}h.succeed();}
    @GameTest public void abortedPreviewRestoresBothActualStockAndFirstFilterWithoutVersionOrEvents(GameTestHelper h){var inventory=new ToolboxInventory();var events=new AtomicInteger();inventory.onChange(events::incrementAndGet);long version=inventory.getVersion();try(var tx=Transaction.openOuter()){h.assertValueEqual(inventory.insert(ItemVariant.of(diamonds()),70,tx),70L,"Real temporary stock inserted");h.assertFalse(inventory.getFilter(0).isEmpty(),"Filter belongs to the same in-flight transaction");}h.assertTrue(inventory.isEmpty()&&inventory.getFilter(0).isEmpty()&&inventory.getVersion()==version&&events.get()==0,"Abort restores stock, filter, version and external notifications together");h.succeed();}
    @GameTest public void nestedCommitCannotEscapeAbortedOuterToolboxCustody(GameTestHelper h){var inventory=stocked(100);var before=inventory.frozenCopy();long version=inventory.getVersion();try(var outer=Transaction.openOuter()){inventory.extract(ItemVariant.of(diamonds()),90,outer);try(var inner=outer.openNested()){inventory.insert(ItemVariant.of(Items.GOLD_INGOT),17,inner);inner.commit();}}h.assertTrue(inventory.equals(before)&&inventory.getVersion()==version,"All original exact variants and eight filters survive nested outer abort");h.succeed();}
    @GameTest public void limitedReturnsUseOnlyActualRetainedFiltersAndCannotClaimAnUnusedCompartment(GameTestHelper h){var inventory=stocked(1);inventory.takeFromCompartment(1,0,false);h.assertFalse(inventory.getFilter(0).isEmpty(),"Actual empty compartment retains its source filter");inventory.inLimitedMode(inv->{try(var tx=Transaction.openOuter()){h.assertValueEqual(inv.insert(ItemVariant.of(Items.GOLD_INGOT),5,tx),0L,"Different stock cannot claim an unconfigured compartment during disposal");h.assertValueEqual(inv.insert(ItemVariant.of(diamonds()),7,tx),7L,"Original established matching compartment accepts a genuine return");tx.commit();}});h.assertTrue(inventory.totalCount(0)==7&&inventory.getFilter(1).isEmpty(),"Only the exact established compartment owns returned stock");h.succeed();}
    @GameTest public void differentDamagedToolsShareACompartmentWithoutLosingTheirOwnComponents(GameTestHelper h){var inventory=new ToolboxInventory();var first=new ItemStack(Items.DIAMOND_PICKAXE);first.setDamageValue(11);first.set(DataComponents.CUSTOM_NAME,Component.literal("First original tool"));var second=new ItemStack(Items.DIAMOND_PICKAXE);second.setDamageValue(37);second.set(DataComponents.CUSTOM_NAME,Component.literal("Second original tool"));try(var tx=Transaction.openOuter()){h.assertValueEqual(inventory.insertCompartment(ItemVariant.of(first),1,0,tx,false),1L,"First actual tool accepted");h.assertValueEqual(inventory.insertCompartment(ItemVariant.of(second),1,0,tx,false),1L,"Second distinct tool shares only its compartment");tx.commit();}h.assertTrue(inventory.totalCount(0)==2&&count(inventory)==2,"Two actual nonstackables retained");ItemStack a=inventory.takeFromCompartment(2,0,false),b=inventory.takeFromCompartment(2,0,false);h.assertTrue(a.getCount()==1&&b.getCount()==1&&(ItemStack.isSameItemSameComponents(a,first)&&ItemStack.isSameItemSameComponents(b,second)||ItemStack.isSameItemSameComponents(a,second)&&ItemStack.isSameItemSameComponents(b,first)),"A single ItemStack never flattens damage/name variants or duplicates tools");h.succeed();}
    @GameTest public void explicitSlotViewsRetainTheirActualContentsUntilTheNativeTransactionFinishes(GameTestHelper h){var inventory=new ToolboxInventory();try(var tx=Transaction.openOuter()){h.assertValueEqual(inventory.getSlot(3).insert(ItemVariant.of(diamonds()),7,tx),7L,"Actual selected Fabric slot accepts stock");h.assertTrue(inventory.getSlot(3).getAmount()==7&&inventory.getSlot(0).isResourceBlank(),"SingleSlotStorage contract is stable while transfers are open");tx.commit();}h.assertTrue(inventory.getSlot(0).getAmount()==7&&inventory.getSlot(3).isResourceBlank(),"Final commit compacts source drawers once without invalidating in-flight slot views");h.succeed();}
    @GameTest public void nativeItemComponentCopiesCannotAliasMutablePlacedStock(GameTestHelper h){var inventory=stocked(70);var item=new ItemStack(AllBlocks.TOOLBOXES.get(DyeColor.BLUE));item.set(AllDataComponents.TOOLBOX_INVENTORY,inventory.frozenCopy());var copy=item.copy();inventory.takeFromCompartment(20,0,false);var component=copy.get(AllDataComponents.TOOLBOX_INVENTORY);h.assertTrue(count(component)==70&&count(inventory)==50,"Native item copy owns the immutable original stock snapshot");component.getStackInSlot(0).setCount(1);component.getFilter(0).setCount(1);h.assertValueEqual(count(component),70L,"Defensive reads cannot change paid item stock");boolean refused=false;try{component.clearContent();}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused&&component.equals(item.get(AllDataComponents.TOOLBOX_INVENTORY)),"Frozen component mutations are refused; actual placed state is copied explicitly");h.succeed();}
    @GameTest public void genuineSparseCodecAndRegistryStreamRetainAllStockAndFilters(GameTestHelper h){var inventory=stocked(100);inventory.setItem(12,new ItemStack(Items.APPLE,9));var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var tag=ToolboxInventory.CODEC.encodeStart(ops,inventory).getOrThrow();h.assertTrue(ToolboxInventory.CODEC.parse(ops,tag).getOrThrow().equals(inventory),"Exact source sparse items/size and eight filters roundtrip");var buffer=new RegistryFriendlyByteBuf(Unpooled.buffer(),h.getLevel().registryAccess());try{ToolboxInventory.STREAM_CODEC.encode(buffer,inventory);h.assertTrue(ToolboxInventory.STREAM_CODEC.decode(buffer).equals(inventory)&&buffer.readableBytes()==0,"Genuine native registry stream has no dropped/trailing stock");}finally{buffer.release();}h.succeed();}
    @GameTest public void originalLegacyInventoryAndComponentAlternativeRemainRegistryAware(GameTestHelper h){var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var legacy=new CompoundTag();legacy.putInt("Size",32);var items=new ListTag();var item=(CompoundTag)ItemStack.CODEC.encodeStart(ops,diamonds().copyWithCount(7)).getOrThrow();item.putByte("Slot",(byte)3);items.add(item);legacy.put("Items",items);var filters=new ListTag();for(int c=0;c<8;c++)filters.add(ItemStack.OPTIONAL_CODEC.encodeStart(ops,c==0?diamonds():ItemStack.EMPTY).getOrThrow());legacy.put("Compartments",filters);var decoded=ToolboxInventory.fromLegacy(h.getLevel().registryAccess(),legacy);h.assertTrue(decoded.totalCount(0)==7&&ItemStack.isSameItemSameComponents(decoded.getFilter(0),diamonds()),"Original Size/Items/Slot/Compartments schema restores actual filtered stock");var contents=ItemContainerContents.fromItems(List.of(diamonds().copyWithCount(5)));h.assertValueEqual(count(ToolboxInventory.BACKWARDS_COMPAT_CODEC.parse(ops,ItemContainerContents.CODEC.encodeStart(ops,contents).getOrThrow()).getOrThrow()),5L,"Source legacy container component alternative retains real stock");h.succeed();}
    @GameTest public void genuineDyeRecipePreservesOriginalPaidContentsNameAndUuid(GameTestHelper h){var box=new ItemStack(AllBlocks.TOOLBOXES.get(DyeColor.BROWN));UUID uuid=UUID.randomUUID();box.set(AllDataComponents.TOOLBOX_UUID,uuid);box.set(AllDataComponents.TOOLBOX_INVENTORY,stocked(100).frozenCopy());box.set(DataComponents.CUSTOM_NAME,Component.literal("Original dyed custody"));var input=CraftingInput.of(2,1,List.of(box,new ItemStack(Items.DYE.pick(DyeColor.CYAN))));var recipe=new ToolboxDyeingRecipe();h.assertTrue(recipe.matches(input,h.getLevel()),"Actual native crafting input matches one box plus one dye");var result=recipe.assemble(input);h.assertTrue(result.is(AllBlocks.TOOLBOXES.get(DyeColor.CYAN).asItem())&&uuid.equals(result.get(AllDataComponents.TOOLBOX_UUID))&&result.getHoverName().getString().equals("Original dyed custody")&&count(result.get(AllDataComponents.TOOLBOX_INVENTORY))==100&&result.get(AllDataComponents.TOOLBOX_INVENTORY)!=box.get(AllDataComponents.TOOLBOX_INVENTORY),"Only color changes; exact immutable paid stock/name/UUID is copied without aliases");h.assertFalse(recipe.matches(CraftingInput.of(3,1,List.of(box,new ItemStack(Items.DYE.pick(DyeColor.CYAN)),new ItemStack(Items.DYE.pick(DyeColor.RED)))),h.getLevel()),"Two dyes cannot produce an extra paid toolbox");h.succeed();}
    @GameTest public void actualPhysicalRecolorKeepsTheSameLiveOwnerAndConsumesNoSourceDye(GameTestHelper h){try(var fixture=place(h,100)){var player=fixture.session.player();var dye=new ItemStack(Items.DYE.pick(DyeColor.CYAN),3);player.setItemInHand(InteractionHand.MAIN_HAND,dye);var pos=fixture.box.getBlockPos();var facing=fixture.box.getBlockState().getValue(ToolboxBlock.FACING);h.assertTrue(h.getBlockState(P).useItemOn(dye,h.getLevel(),player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false)).consumesAction(),"Real native dye use reaches the physical source block");var result=h.getBlockEntity(P,ToolboxBlockEntity.class);h.assertTrue(result==fixture.box&&result.getColor()==DyeColor.CYAN&&result.getUniqueId().equals(fixture.uuid)&&count(result.inventory)==100&&dye.getCount()==3&&result.getBlockState().getValue(ToolboxBlock.FACING)==facing,"Cross-color native block replacement retains the exact live BE, paid inventory, UUID, facing and source non-consuming dye semantics");}h.succeed();}
    @GameTest public void physicalAttackPicksUpExactlyOneWholePaidBox(GameTestHelper h){try(var fixture=place(h,100)){var player=fixture.session.player();var snapshot=fixture.box.inventory.frozenCopy();h.getBlockState(P).attack(h.getLevel(),h.absolutePos(P),player);h.assertTrue(h.getBlockState(P).isAir()&&player.getInventory().countItem(AllBlocks.TOOLBOXES.get(DyeColor.BROWN).asItem())==1,"Real native attack removes one source block and returns one toolbox item");ItemStack returned=ItemStack.EMPTY;for(int slot=0;slot<36;slot++){var value=player.getInventory().getItem(slot);if(value.is(AllBlocks.TOOLBOXES.get(DyeColor.BROWN).asItem()))returned=value;}h.assertTrue(fixture.uuid.equals(returned.get(AllDataComponents.TOOLBOX_UUID))&&snapshot.equals(returned.get(AllDataComponents.TOOLBOX_INVENTORY))&&returned.getHoverName().getString().equals("Paid source toolbox")&&h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(1)).isEmpty(),"Only the exact original UUID/name/filtered stock returns; no loose inventory/drop duplicate exists");}h.succeed();}
    @GameTest public void blockLootCarriesNativeWholeBoxComponentsExactlyOnce(GameTestHelper h){try(var fixture=place(h,100)){h.assertTrue(h.getLevel().destroyBlock(h.absolutePos(P),true),"Actual vanilla destruction evaluates registered native loot");var drops=h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(2));h.assertTrue(drops.size()==1&&drops.getFirst().getItem().getCount()==1&&fixture.uuid.equals(drops.getFirst().getItem().get(AllDataComponents.TOOLBOX_UUID))&&count(drops.getFirst().getItem().get(AllDataComponents.TOOLBOX_INVENTORY))==100,"Original copy_name/copy_components loot returns the whole actual box once");}h.succeed();}
    @GameTest(maxTicks=35) public void genuineLinkedHotbarReplenishmentAndReturnConserveTheOriginalStock(GameTestHelper h){var fixture=place(h,100);equip(fixture,0);h.runAfterDelay(2,()->{var player=fixture.session.player();h.assertTrue(player.getInventory().getItem(0).getCount()==32&&count(fixture.box.inventory)==68,"Natural BE ticks move actual half-stack stock into the linked player slot");ToolboxHandler.unequip(player,0,false);h.assertTrue(player.getInventory().getItem(0).isEmpty()&&count(fixture.box.inventory)==100&&ToolboxBindings.get(player,0)==null,"Genuine unequip atomically returns original owned items and removes the persistent link");fixture.close();h.succeed();});}
    @GameTest public void realDisposalRespectsRetainedFiltersAndPreservesEveryIncompatibleItem(GameTestHelper h){try(var fixture=place(h,1)){var player=fixture.session.player();player.getInventory().setItem(0,diamonds().copyWithCount(7));player.getInventory().setItem(9,new ItemStack(Items.GOLD_INGOT,11));equip(fixture,0);new ToolboxDisposeAllPacket(fixture.box.getBlockPos(),fixture.uuid).handle(player);h.assertTrue(player.getInventory().getItem(0).isEmpty()&&player.getInventory().getItem(9).getCount()==11&&player.getInventory().getItem(9).is(Items.GOLD_INGOT)&&count(fixture.box.inventory)==8&&fixture.box.inventory.getFilter(1).isEmpty()&&ToolboxBindings.get(player,0)==null,"Only established matching stock moves through actual player/Fabric slots; incompatible gold and unused filters remain unchanged");}h.succeed();}
    @GameTest(maxTicks=35) public void openingTheActualNativeMenuDetachesConflictingAutoReplenishment(GameTestHelper h){var fixture=place(h,100);var player=fixture.session.player();equip(fixture,0);h.assertTrue(player.openMenu(fixture.box).isPresent()&&player.containerMenu instanceof ToolboxMenu,"Actual native extended menu opens on its genuine loaded owner");h.runAfterDelay(2,()->{h.assertTrue(player.getInventory().getItem(0).isEmpty()&&count(fixture.box.inventory)==100&&ToolboxBindings.get(player,0)==null,"Source open-menu interference detaches the actual binding without taking phantom player stock");fixture.close();h.succeed();});}
    @GameTest public void realMenuHiddenSlotsShiftClickAndEmptyRepresentativeFilterClearingOperateOnOneOwner(GameTestHelper h){try(var fixture=place(h,100)){var player=fixture.session.player();player.openMenu(fixture.box);var menu=(ToolboxMenu)player.containerMenu;h.assertTrue(menu.slots.size()==68&&menu.getSlot(0).isActive()&&!menu.getSlot(1).isActive()&&menu.totalCountInCompartment(0)==100,"All32 genuine toolbox slots plus36 player slots use source representative visibility");menu.quickMoveStack(player,0);menu.quickMoveStack(player,0);h.assertTrue(fixture.box.inventory.isEmpty()&&player.getInventory().countItem(Items.DIAMOND)==100&&!menu.getFilter(0).isEmpty(),"Vanilla native shift-click debits actual stock while retaining its filter");menu.clicked(0,0,ContainerInput.PICKUP,player);h.assertTrue(menu.getFilter(0).isEmpty(),"Only a real empty representative/empty cursor click clears the retained source filter");}h.succeed();}
    @GameTest public void differentOrOutOfRangeNativePacketOwnersCannotClaimAnotherBox(GameTestHelper h){try(var fixture=place(h,100)){var player=fixture.session.player();new ToolboxEquipPacket(fixture.box.getBlockPos(),UUID.randomUUID(),0,0).handle(player);new ToolboxEquipPacket(fixture.box.getBlockPos(),fixture.uuid,0,99).handle(player);h.assertTrue(ToolboxBindings.get(player,0)==null&&count(fixture.box.inventory)==100,"Wrong UUID and invalid hotbar packet cannot establish ownership or take stock");var away=Vec3.atCenterOf(fixture.box.getBlockPos()).add(0,0,ToolboxConfig.get(h.getLevel())+5);h.assertTrue(player.teleportTo(h.getLevel(),away.x,away.y,away.z,Set.of(),0,0,false),"Actual player moves outside configured native range");new ToolboxEquipPacket(fixture.box.getBlockPos(),fixture.uuid,0,0).handle(player);new ToolboxDisposeAllPacket(fixture.box.getBlockPos(),fixture.uuid).handle(player);h.assertTrue(ToolboxBindings.get(player,0)==null&&count(fixture.box.inventory)==100,"Real out-of-range packets cannot fabricate a nearby link or disposal");}h.succeed();}
    @GameTest public void sourceLegacyPlayerDataMigratesIntoRealPersistentOwnerSyncedAttachment(GameTestHelper h){try(var fixture=place(h,100)){var player=fixture.session.player();var old=new CompoundTag();var entry=new CompoundTag();var pos=new CompoundTag();pos.putInt("X",fixture.box.getBlockPos().getX());pos.putInt("Y",fixture.box.getBlockPos().getY());pos.putInt("Z",fixture.box.getBlockPos().getZ());entry.put("Pos",pos);entry.putInt("Slot",0);old.put("0",entry);var holder=new CompoundTag();holder.put("CreateToolboxData",old);var root=new CompoundTag();root.put("NeoForgeData",holder);ToolboxBindings.migrate(player,TagValueInput.create(ProblemReporter.DISCARDING,h.getLevel().registryAccess(),root));h.assertTrue(ToolboxBindings.matches(player,ToolboxBindings.get(player,0),fixture.box),"Genuine original NeoForgeData/CreateToolboxData/Pos/Slot resolves the actual loaded owner");ToolboxBindings.set(player,0,fixture.box,0);var output=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,h.getLevel().registryAccess());player.saveWithoutId(output);h.assertTrue(output.buildResult().toString().contains("toolbox_bindings")&&fixture.uuid.equals(ToolboxBindings.get(player,0).owner()),"Actual native player save persists the platform attachment and exact modern owner UUID");}h.succeed();}
    @GameTest(maxTicks=120) public void physicalMountedCaptureSaveReloadAndRestorationRetainExactFiltersAndExpireOldHandles(GameTestHelper h){var fixture=place(h,100);h.startSequence().thenWaitUntil(()->{var checked=new HashSet<Long>();try{for(var relative:List.of(P,P.below(),T)){var pos=h.absolutePos(relative);com.simibubi.create.foundation.utility.LoadedEntityAccess.requireReady(h.getLevel(),pos);com.simibubi.create.foundation.utility.LoadedEntityAccess.requireGlueQueriesReady(h.getLevel(),pos,checked);}}catch(AssemblyException pending){throw h.assertionException("Actual native Toolbox capture/glue query visibility is pending at "+pending.getPosition());}}).thenExecute(()->{try(fixture){Storage<ItemVariant> world=ItemStorage.SIDED.find(h.getLevel(),h.absolutePos(P),null);h.assertTrue(world!=null&&count(world)==100,"Actual registered Fabric world storage exposes original paid stock");var structure=new BearingContraption(false,Direction.EAST);h.assertTrue(structure.assemble(h.getLevel(),h.absolutePos(P.west())),"Genuine physical source box is discovered by the registered contraption");var old=structure.getStorage().getAllItemStorages().get(BlockPos.ZERO);h.assertValueEqual(count(old),0L,"Pre-removal mounted snapshot cannot steal world-owned toolbox stock");h.assertTrue(structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO)&&h.getBlockState(P).isAir(),"Actual native capture removes the whole world toolbox and transfers custody");var mounted=structure.getStorage().getAllItemStorages().get(BlockPos.ZERO);h.assertTrue(mounted instanceof ToolboxMountedStorage&&count(mounted)==100&&count(world)==0,"Only refreshed actual mounted storage owns paid stock; stale world capability expires");try(var tx=Transaction.openOuter()){h.assertValueEqual(mounted.extract(ItemVariant.of(diamonds()),37,tx),37L,"Real mounted actor transfer removes original items");tx.commit();}var restored=Contraption.fromNBT(h.getLevel(),structure.writeNBT(h.getLevel().registryAccess(),false),false);var current=restored.getStorage().getAllItemStorages().get(BlockPos.ZERO);var held=current.getSlot(0);h.assertTrue(count(current)==63&&restored.tryAddBlocksToWorld(h.getLevel(),new StructureTransform(h.absolutePos(T),0,90,0)),"Actual saved mounted stock restores through the native transformed contraption path");var box=h.getBlockEntity(T,ToolboxBlockEntity.class);h.assertTrue(count(box.inventory)==63&&ItemStack.isSameItemSameComponents(box.inventory.getFilter(0),diamonds())&&fixture.uuid.equals(box.getUniqueId())&&box.getDisplayName().getString().equals("Paid source toolbox"),"World restores exact original UUID/name/filter and only the63 still-owned diamonds");try(var tx=Transaction.openOuter()){h.assertValueEqual(current.extract(ItemVariant.of(diamonds()),1,tx),0L,"Retired mounted owner cannot duplicate restored stock");h.assertValueEqual(held.insert(ItemVariant.of(diamonds()),1,tx),0L,"Held mounted slot cannot mutate the retired owner");tx.commit();}}catch(RuntimeException failure){throw failure;}catch(Exception failure){throw new RuntimeException(failure);}}).thenSucceed();}

    @GameTest public void incompatibleEquippedStockReturnsThroughActualMainSlotsWithoutClaimingNewFilters(GameTestHelper h){try(var fixture=place(h,100)){var player=fixture.session.player();player.getInventory().setItem(0,new ItemStack(Items.GOLD_INGOT,7));equip(fixture,0);h.assertTrue(player.getInventory().getItem(0).isEmpty()&&player.getInventory().getItem(9).is(Items.GOLD_INGOT)&&player.getInventory().getItem(9).getCount()==7&&fixture.box.inventory.totalCount(0)==100&&fixture.box.inventory.getFilter(1).isEmpty(),"Actual incompatible hotbar stock atomically returns to genuine player main slots rather than claiming unused toolbox filters");}h.succeed();}
    @GameTest public void genuineBeltReturnClearsOnlyTheTransientFirstShaftComponent(GameTestHelper h){try(var fixture=place(h,0)){var player=fixture.session.player();var belt=new ItemStack(AllItems.BELT_CONNECTOR);belt.set(DataComponents.CUSTOM_NAME,Component.literal("Original returned belt"));fixture.box.inventory.setItem(0,belt);var held=belt.copyWithCount(2);held.set(AllDataComponents.BELT_FIRST_SHAFT,h.absolutePos(P.south()));player.getInventory().setItem(0,held);h.assertValueEqual(ToolboxHandler.returnItems(player,fixture.box,0,0,2,false),2,"Actual native belt metadata conversion and cross-inventory return commits");var stored=fixture.box.inventory.getStackInSlot(0);h.assertTrue(player.getInventory().getItem(0).isEmpty()&&stored.getCount()==3&&!stored.has(AllDataComponents.BELT_FIRST_SHAFT)&&stored.getHoverName().getString().equals("Original returned belt"),"Only original transient first-shaft data is removed; all3 real belts and their name remain owned once");}h.succeed();}

    @GameTest public void sourceBoundedSparseSizesRetainActualThirtyTwoSlotsAndRejectEntriesOutsideTheDeclaredSize(GameTestHelper h){var ops=h.getLevel().registryAccess().createSerializationContext(NbtOps.INSTANCE);var data=(CompoundTag)ToolboxInventory.CODEC.encodeStart(ops,stocked(7)).getOrThrow();data.getCompoundOrEmpty("items").putInt("size",1);var sparse=ToolboxInventory.CODEC.parse(ops,data).getOrThrow();h.assertTrue(sparse.getSlotCount()==32&&sparse.totalCount(0)==7&&ItemStack.isSameItemSameComponents(sparse.getFilter(0),diamonds()),"Original maxSizeCodec accepts a smaller bounded sparse payload while actual Toolbox always owns32 native slots and eight retained filters");var empty=data.copy();var slots=new CompoundTag();slots.put("items",new CompoundTag());slots.putInt("size",0);empty.put("items",slots);var zero=ToolboxInventory.CODEC.parse(ops,empty).getOrThrow();h.assertTrue(zero.getSlotCount()==32&&zero.isEmpty()&&!zero.getFilter(0).isEmpty(),"Genuine size-zero source sparse payload retains the actual original filter without inventing stock");var invalid=data.copy();invalid.getCompoundOrEmpty("items").putInt("size",0);h.assertTrue(ToolboxInventory.CODEC.parse(ops,invalid).error().isPresent(),"Actual sparse index0 cannot lie outside declared size0");invalid.getCompoundOrEmpty("items").putInt("size",33);h.assertTrue(ToolboxInventory.CODEC.parse(ops,invalid).error().isPresent(),"Source max32 boundary rejects an oversized sparse record");h.succeed();}
}
